var lines = [];
var title = '';
try {
  var d = Packages.org.jsoup.Jsoup.parse(html);
  var pt = d.select('.preview-text');
  if (pt.size() > 0) {
    var h = String(pt.get(0).html()).replace(/<br\s*\/?>/gi, NL);
    h = String(Packages.org.jsoup.parser.Parser.unescapeEntities(h, true));
    h = h.replace(/<[^>]+>/g, '');
    lines = String(h).split(NL);
  }
  var nm = d.select('.ph-name');
  if (nm.size() > 0) title = String(nm.get(0).text());
} catch (e1) {}
var name = '';
var i;
for (i = 0; i < lines.length; i++) {
  var m = clean(lines[i]).match(/^作\s*者\s*[\s:：]+(.+)$/);
