  var m3 = clean(title).match(/作\s*者\s*[\s:：]+(.+)$/);
  if (m3) name = pick(m3[1]);
}
if (!name) {
  for (i = 0; i < lines.length && i < 6; i++) {
    var m4 = clean(lines[i]).match(/^.{2,40}?[bB][yY]([^bB\s]{1,16})$/);
    if (m4) { name = pick(m4[1]); if (name) break; }
  }
}
if (!name) {
  var flat = String(html).replace(/<[^>]+>/g, ' ');
  var m5 = flat.match(/作\s*者\s*[\s:：]+\s*([^\s，。；、！？!?*（）()【】\[\]{}《》"']{1,18})/);
